"use client";
/* eslint-disable @typescript-eslint/no-unused-vars -- legacy standalone Copilot implementation is no longer routed */

import Link from "next/link";
import { useRouter } from "next/navigation";
import { FormEvent, ReactNode, useEffect, useState } from "react";
import { api, clearStoredSession, isUnauthorized } from "../../lib/api";
import { NotificationBell } from "./notification-bell";
import { ResumeBuilderHome } from "./resume-builder";
export type EmployeeSectionName = "reports" | "compare-resumes" | "resume-builder" | "interview-practice" | "settings" | "help";
type Profile = { full_name: string; email: string; role: "employee" | "hr" };
type Analysis = { id: number; original_filename: string; job_title: string; overall_score: number; status: string; created_at: string };
type JobApplication = { id: number; company: string; role: string; appliedOn: string; status: "Saved" | "Applied" | "Interview" | "Offer" | "Rejected"; resume: string; nextStep: string };
type ComparisonAnalysis = Analysis & { impact_score:number; clarity_score:number; ats_score:number; detailed_report?:{ strengths?:string[]; matched_keywords?:string[]; missing_keywords?:string[] } };
type IconName = "home" | "document" | "chart" | "versions" | "calendar" | "spark" | "settings" | "help" | "bell" | "search" | "plus" | "arrow" | "download" | "more" | "clock" | "play" | "mic" | "message" | "target" | "bookmark" | "send" | "user" | "lock" | "palette" | "question" | "mail" | "book" | "check";

const nav: { label: string; icon: IconName; href: string; section?: EmployeeSectionName; badge?: string }[] = [
  { label: "Overview", icon: "home", href: "/employee/dashboard" },
  { label: "Resume Analyzer", icon: "document", href: "/employee/resume-analyzer", section: "reports" },
  { label: "Compare Resumes", icon: "versions", href: "/employee/compare-resumes", section: "compare-resumes" },
  { label: "Resume Builder", icon: "document", href: "/employee/resume-builder", section: "resume-builder" },
  { label: "Interview Practice", icon: "calendar", href: "/employee/interview-practice", section: "interview-practice" },
];

const titles: Record<EmployeeSectionName, [string, string]> = {
  reports: ["Resume Analyzer", "Review previous analyses or start a new resume review."],
  "compare-resumes": ["Compare Resumes", "Compare two analyzed resumes and choose the stronger version."],
  "resume-builder": ["Resume Builder", "Create, edit, and manage tailored professional resumes."],
  "interview-practice": ["Interview Practice", "Build confidence with focused, AI-guided practice sessions."],
  settings: ["Settings", "Manage your profile, preferences, and privacy."],
  help: ["Help Center", "Find answers and get the support you need."],
};

export function EmployeeSection({ section }: { section: EmployeeSectionName }) {
  const router = useRouter();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [analyses, setAnalyses] = useState<Analysis[]>([]);
  const [analysesLoading, setAnalysesLoading] = useState(section === "reports");
  useEffect(() => {
    const role = localStorage.getItem("userRole") ?? sessionStorage.getItem("userRole");
    const token = localStorage.getItem("accessToken") ?? sessionStorage.getItem("accessToken");
    if (!token || role !== "employee") { router.replace(role === "hr" ? "/hr/dashboard" : "/"); return; }
    api.get<Profile>("/api/auth/profile/")
      .then(({ data: user }) => { if (user.role === "employee") setProfile(user); })
      .catch((error) => { if (isUnauthorized(error)) { clearSession(); router.replace("/"); } });
  }, [router]);
  useEffect(() => {
    if (section !== "reports") return;
    const token = localStorage.getItem("accessToken") ?? sessionStorage.getItem("accessToken");
    if (!token) return;
    api.get<Analysis[]>("/api/resumes/analyses/")
      .then(({ data: items }) => setAnalyses(items))
      .catch(() => setAnalyses([]))
      .finally(() => setAnalysesLoading(false));
  }, [section]);
  function clearSession() { clearStoredSession(); }
  const initials = profile?.full_name.split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase() || "EU";

  return <main className="min-h-screen bg-[#f7f8fa] text-slate-950"><div className="grid min-h-screen lg:grid-cols-[230px_1fr]">
    <aside className="flex flex-col border-b border-slate-200 bg-white px-4 py-4 lg:fixed lg:inset-y-0 lg:w-[230px] lg:border-b-0 lg:border-r">
      <Brand /><p className="mb-2 mt-6 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-400">Workspace</p>
      <nav className="grid grid-cols-2 gap-1 sm:grid-cols-4 lg:grid-cols-1" aria-label="Employee navigation">{nav.map((item) => <NavItem key={item.label} {...item} active={item.section === section} />)}</nav>
      <div className="mt-auto hidden lg:block"><p className="mb-2 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-400">Account</p><NavItem label="Settings" icon="settings" href="/employee/settings" active={section === "settings"} /><NavItem label="Help center" icon="help" href="/employee/help" active={section === "help"} /><div className="mt-5 border-t border-slate-100 pt-5"><div className="flex items-center gap-3 rounded-xl p-2"><Avatar text={initials.slice(0,1)} /><div className="min-w-0 flex-1"><strong className="block truncate text-xs">{profile?.full_name || "Loading profile..."}</strong><span className="block truncate text-[10px] text-slate-500">{profile?.email || "Employee"}</span></div></div><button type="button" onClick={() => { clearSession(); router.replace("/"); router.refresh(); }} className="mt-2 w-full rounded-lg px-3 py-2 text-left text-xs font-semibold text-slate-500 hover:bg-red-50 hover:text-red-700">Log out</button></div></div>
    </aside>
    <section className="min-w-0 lg:col-start-2"><TopBar initials={initials} section={section} /><div className="w-full px-5 py-4 sm:px-6 lg:px-7">{section === "reports" && <Reports analyses={analyses} loading={analysesLoading} onDeleted={(id) => setAnalyses((items) => items.filter((item) => item.id !== id))} />}{section === "compare-resumes" && <CompareResumes />}{section === "resume-builder" && <ResumeBuilderHome/>}{section === "interview-practice" && <Interview />}{section === "settings" && <Settings profile={profile} />}{section === "help" && <Help />}</div></section>
  </div></main>;
}

function Reports({ analyses, loading, onDeleted }: { analyses: Analysis[]; loading: boolean; onDeleted: (id:number)=>void }) { const [query,setQuery]=useState(""); const [status,setStatus]=useState("All"); const filtered=analyses.filter((item)=>(status==="All"||item.status===status)&&`${item.original_filename} ${item.job_title}`.toLowerCase().includes(query.toLowerCase())); return <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-col gap-4 border-b border-slate-100 p-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2"><h2 className="text-lg font-bold">Resume analysis history</h2><span className="rounded-full bg-blue-50 px-2.5 py-1 text-[9px] font-bold text-blue-700">{analyses.length} {analyses.length===1?"analysis":"analyses"}</span></div><p className="mt-1 text-[11px] text-slate-500">Only resumes you analyze will appear here.</p></div>{analyses.length>0&&<div className="flex flex-col gap-2 sm:flex-row"><input value={query} onChange={(event)=>setQuery(event.target.value)} aria-label="Search analysis history" placeholder="Search by resume or role..." className="h-9 rounded-lg bg-slate-50 px-3 text-xs outline-none focus:ring-2 focus:ring-blue-100"/><select value={status} onChange={(event)=>setStatus(event.target.value)} aria-label="Filter by status" className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-[10px] font-bold text-slate-600 outline-none"><option>All</option><option>Excellent</option><option>Strong</option><option>Good</option><option>Needs work</option></select></div>}</div>{loading?<div className="grid min-h-64 place-items-center text-xs font-semibold text-slate-400">Loading analysis history...</div>:analyses.length===0?<div className="grid min-h-72 place-items-center px-5 text-center"><div><span className="mx-auto grid size-12 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon name="document"/></span><h3 className="mt-4 text-sm font-bold">No analyses yet</h3><p className="mt-1 text-[10px] text-slate-500">Analyze your first resume and its result will be saved here.</p><Link href="/employee/resume-analyzer" className="mt-5 inline-flex h-9 items-center gap-2 rounded-lg bg-blue-700 px-4 text-[10px] font-bold text-white"><Icon name="plus"/> Analyze a resume</Link></div></div>:<><div className="overflow-x-auto"><table className="w-full min-w-[900px] border-collapse text-left"><thead><tr className="border-b border-slate-200 bg-slate-50/80 text-[9px] font-bold uppercase tracking-[0.12em] text-slate-500"><th className="px-5 py-3.5">Resume</th><th className="px-5 py-3.5">Target role</th><th className="px-5 py-3.5">Analyzed on</th><th className="px-5 py-3.5 text-center">Score</th><th className="px-5 py-3.5">Status</th><th className="px-5 py-3.5 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100">{filtered.map((item)=><Report key={item.id} item={item} onDeleted={onDeleted}/>)}</tbody></table></div>{filtered.length===0&&<p className="border-t border-slate-100 px-5 py-10 text-center text-xs text-slate-500">No analyses match your search or filter.</p>}<div className="border-t border-slate-100 px-5 py-4 text-[10px] text-slate-500">Showing {filtered.length} of {analyses.length} analyses</div></>}</section>; }
function Report({ item, onDeleted }: { item:Analysis; onDeleted:(id:number)=>void }) {
  const router=useRouter();
  const [open,setOpen]=useState(false);
  const [busy,setBusy]=useState(false);
  const statusStyles:Record<string,string>={Excellent:"bg-emerald-50 text-emerald-700",Strong:"bg-blue-50 text-blue-700",Good:"bg-sky-50 text-sky-700","Needs work":"bg-amber-50 text-amber-700"};
  // Each history row links to the detailed report belonging to this analysis.
  const reportUrl=`/employee/reports/${item.id}`;
  async function download(){setBusy(true);try{const response=await api.get(`/api/resumes/analyses/${item.id}/download/`,{responseType:"blob"});const url=URL.createObjectURL(response.data);const anchor=document.createElement("a");anchor.href=url;anchor.download=item.original_filename;anchor.click();URL.revokeObjectURL(url);}finally{setBusy(false);setOpen(false);}}
  async function remove(){if(!window.confirm(`Delete the analysis for ${item.original_filename}?`))return;setBusy(true);try{await api.delete(`/api/resumes/analyses/${item.id}/`);onDeleted(item.id);}finally{setBusy(false);setOpen(false);}}
  const date=new Date(item.created_at).toLocaleDateString(undefined,{year:"numeric",month:"long",day:"numeric"});
  // The whole row replaces the old separate "View report" button. Keyboard
  // handling keeps the same navigation accessible with Enter or Space.
  return <tr tabIndex={0} aria-label={`Open report for ${item.original_filename}`} onClick={()=>router.push(reportUrl)} onKeyDown={(event)=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();router.push(reportUrl);}}} className="cursor-pointer transition hover:bg-blue-50/50 focus:bg-blue-50/50 focus:outline-none">
    <td className="px-5 py-4"><div className="flex items-center gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-blue-50 text-blue-700"><Icon name="document"/></span><div><strong className="block text-[11px] text-slate-900">{item.original_filename}</strong><span className="mt-1 block text-[9px] text-slate-400">Resume document</span></div></div></td>
    <td className="px-5 py-4 text-[11px] font-medium text-slate-700">{item.job_title}</td><td className="px-5 py-4 text-[10px] text-slate-500">{date}</td><td className="px-5 py-4 text-center"><strong className="text-base text-slate-950">{item.overall_score}</strong><span className="text-[9px] text-slate-400">/100</span></td><td className="px-5 py-4"><span className={`inline-flex rounded-full px-2.5 py-1 text-[9px] font-bold ${statusStyles[item.status]}`}>{item.status}</span></td>
    {/* Stop bubbling here so opening a menu action does not also open the row. */}
    <td className="px-5 py-4" onClick={(event)=>event.stopPropagation()} onKeyDown={(event)=>event.stopPropagation()}><div className="relative flex items-center justify-end"><button type="button" onClick={()=>setOpen((value)=>!value)} aria-expanded={open} aria-label={`More options for ${item.original_filename}`} className="grid size-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100"><Icon name="more"/></button>{open&&<div className="absolute right-0 top-10 z-20 w-40 overflow-hidden rounded-xl border border-slate-200 bg-white p-1.5 text-left shadow-xl"><Link href={reportUrl} className="block rounded-lg px-3 py-2 text-[10px] font-semibold hover:bg-slate-50">View report</Link><button type="button" disabled={busy} onClick={()=>void download()} className="block w-full rounded-lg px-3 py-2 text-left text-[10px] font-semibold hover:bg-slate-50">Download resume</button><Link href="/employee/resume-analyzer/new" className="block rounded-lg px-3 py-2 text-[10px] font-semibold hover:bg-slate-50">Analyze again</Link><button type="button" disabled={busy} onClick={()=>void remove()} className="block w-full rounded-lg px-3 py-2 text-left text-[10px] font-semibold text-red-600 hover:bg-red-50">Delete analysis</button></div>}</div></td>
  </tr>;
}

function CompareResumes() {
  const [reports,setReports]=useState<ComparisonAnalysis[]>([]);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState("");
  const [leftId,setLeftId]=useState<number|null>(null);
  const [rightId,setRightId]=useState<number|null>(null);

  useEffect(()=>{
    api.get<ComparisonAnalysis[]>("/api/resumes/analyses/")
      .then(({data})=>{
        setReports(data);
        setLeftId(data[0]?.id??null);
        setRightId(data[1]?.id??null);
      })
      .catch(()=>setError("Resume analyses could not be loaded."))
      .finally(()=>setLoading(false));
  },[]);

  const left=reports.find((report)=>report.id===leftId);
  const right=reports.find((report)=>report.id===rightId);
  if(loading)return <section className="grid min-h-72 place-items-center rounded-2xl border border-slate-200 bg-white text-xs font-semibold text-slate-400">Loading analyzed resumes...</section>;
  if(error)return <section className="grid min-h-72 place-items-center rounded-2xl border border-red-100 bg-white text-xs font-semibold text-red-600">{error}</section>;
  if(reports.length<2)return <section className="grid min-h-80 place-items-center rounded-2xl border border-slate-200 bg-white px-6 text-center shadow-sm"><div><span className="mx-auto grid size-12 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon name="versions"/></span><h2 className="mt-4 text-base font-bold">Analyze at least two resumes</h2><p className="mt-1 text-[10px] text-slate-500">You need two saved analysis reports before you can compare their results.</p><Link href="/employee/resume-analyzer/new" className="mt-5 inline-flex h-9 items-center gap-2 rounded-lg bg-blue-700 px-4 text-[10px] font-bold text-white"><Icon name="plus"/> New analysis</Link></div></section>;
  if(!left||!right)return null;
  const winner=left.overall_score===right.overall_score?null:left.overall_score>right.overall_score?left:right;
  return <div className="space-y-4"><section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-col gap-1"><h2 className="text-base font-bold">Select resumes to compare</h2><p className="text-[10px] text-slate-500">Choose two different analysis reports.</p></div><div className="mt-4 grid gap-3 md:grid-cols-[1fr_auto_1fr]"><CompareSelect label="Resume A" value={left.id} reports={reports} excludedId={right.id} onChange={setLeftId}/><span className="hidden self-end pb-2 text-xs font-bold text-slate-400 md:block">VS</span><CompareSelect label="Resume B" value={right.id} reports={reports} excludedId={left.id} onChange={setRightId}/></div></section>
    {winner&&<section className="flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3"><span className="grid size-8 place-items-center rounded-lg bg-emerald-600 text-white"><Icon name="check"/></span><div><strong className="block text-xs">Stronger overall match: {winner.original_filename}</strong><span className="text-[10px] text-emerald-700">It leads by {Math.abs(left.overall_score-right.overall_score)} overall score {Math.abs(left.overall_score-right.overall_score)===1?"point":"points"}.</span></div></section>}
    <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="grid grid-cols-[140px_1fr_1fr] border-b border-slate-200 bg-slate-50 text-[10px] font-bold sm:grid-cols-[220px_1fr_1fr]"><span className="p-4 text-slate-500">Comparison</span><CompareHeading report={left}/><CompareHeading report={right}/></div><CompareScoreRow label="Overall score" left={left.overall_score} right={right.overall_score}/><CompareScoreRow label="Impact" left={left.impact_score} right={right.impact_score}/><CompareScoreRow label="Clarity" left={left.clarity_score} right={right.clarity_score}/><CompareScoreRow label="ATS match" left={left.ats_score} right={right.ats_score}/><CompareTextRow label="Target role" left={left.job_title} right={right.job_title}/><CompareListRow label="Top strengths" left={left.detailed_report?.strengths} right={right.detailed_report?.strengths}/><CompareListRow label="Matched keywords" left={left.detailed_report?.matched_keywords} right={right.detailed_report?.matched_keywords}/><CompareListRow label="Missing keywords" left={left.detailed_report?.missing_keywords} right={right.detailed_report?.missing_keywords}/></section>
  </div>;
}
function CompareSelect({label,value,reports,excludedId,onChange}:{label:string;value:number;reports:ComparisonAnalysis[];excludedId:number;onChange:(id:number)=>void}){return <label><span className="text-[9px] font-bold uppercase tracking-wider text-slate-500">{label}</span><select value={value} onChange={(event)=>onChange(Number(event.target.value))} className="mt-1 h-11 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs outline-none focus:border-blue-400"><option value={value}>{reports.find((item)=>item.id===value)?.original_filename}</option>{reports.filter((item)=>item.id!==value&&item.id!==excludedId).map((item)=><option key={item.id} value={item.id}>{item.original_filename} — {item.job_title}</option>)}</select></label>}
function CompareHeading({report}:{report:ComparisonAnalysis}){return <div className="border-l border-slate-200 p-4"><strong className="block truncate text-xs">{report.original_filename}</strong><span className="mt-1 block truncate text-[9px] font-normal text-slate-500">{report.job_title}</span></div>}
function CompareScoreRow({label,left,right}:{label:string;left:number;right:number}){const best=Math.max(left,right);return <div className="grid grid-cols-[140px_1fr_1fr] border-b border-slate-100 last:border-0 sm:grid-cols-[220px_1fr_1fr]"><strong className="p-4 text-[10px] text-slate-600">{label}</strong>{[left,right].map((value,index)=><div key={index} className="border-l border-slate-100 p-4"><div className="flex items-center justify-between"><b className={value===best&&left!==right?"text-blue-700":""}>{value}/100</b>{value===best&&left!==right&&<span className="rounded-full bg-blue-50 px-2 py-0.5 text-[8px] font-bold text-blue-700">Higher</span>}</div><div className="mt-2 h-1.5 rounded-full bg-slate-100"><div className="h-full rounded-full bg-blue-600" style={{width:`${value}%`}}/></div></div>)}</div>}
function CompareTextRow({label,left,right}:{label:string;left:string;right:string}){return <div className="grid grid-cols-[140px_1fr_1fr] border-b border-slate-100 sm:grid-cols-[220px_1fr_1fr]"><strong className="p-4 text-[10px] text-slate-600">{label}</strong><span className="border-l border-slate-100 p-4 text-[10px]">{left}</span><span className="border-l border-slate-100 p-4 text-[10px]">{right}</span></div>}
function CompareListRow({label,left=[],right=[]}:{label:string;left?:string[];right?:string[]}){return <div className="grid grid-cols-[140px_1fr_1fr] border-b border-slate-100 last:border-0 sm:grid-cols-[220px_1fr_1fr]"><strong className="p-4 text-[10px] text-slate-600">{label}</strong>{[left,right].map((items,index)=><div key={index} className="border-l border-slate-100 p-4"><ul className="space-y-1.5">{items.slice(0,4).map((item)=><li key={item} className="flex gap-2 text-[9px] leading-4 text-slate-600"><span className="mt-1.5 size-1 shrink-0 rounded-full bg-blue-600"/>{item}</li>)}</ul>{items.length===0&&<span className="text-[9px] text-slate-400">Not available in this report</span>}</div>)}</div>}

function JobApplications() {
  const [applications, setApplications] = useState<JobApplication[]>([
    { id: 1, company: "Northstar Labs", role: "Senior Product Designer", appliedOn: "2026-08-29", status: "Interview", resume: "Product Designer Resume.pdf", nextStep: "Interview · Sep 03" },
    { id: 2, company: "Finora", role: "UX Designer", appliedOn: "2026-08-26", status: "Applied", resume: "UX Designer — Fintech.pdf", nextStep: "Awaiting response" },
    { id: 3, company: "PixelCraft", role: "Product Designer", appliedOn: "2026-08-21", status: "Offer", resume: "Product Designer Resume.pdf", nextStep: "Review offer" },
    { id: 4, company: "Aster Technologies", role: "UX Researcher", appliedOn: "2026-08-17", status: "Saved", resume: "General Resume.pdf", nextStep: "Submit application" },
  ]);
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("All");
  const [showForm, setShowForm] = useState(false);
  const [company, setCompany] = useState("");
  const [role, setRole] = useState("");
  const [resume, setResume] = useState("General Resume.pdf");
  const [status, setStatus] = useState<JobApplication["status"]>("Saved");
  const filtered = applications.filter((item) => (filter === "All" || item.status === filter) && `${item.company} ${item.role} ${item.resume}`.toLowerCase().includes(query.toLowerCase()));
  const counts = { total: applications.length, active: applications.filter((item) => ["Applied", "Interview"].includes(item.status)).length, interviews: applications.filter((item) => item.status === "Interview").length, offers: applications.filter((item) => item.status === "Offer").length };
  function addApplication(event: FormEvent) {
    event.preventDefault();
    if (!company.trim() || !role.trim()) return;
    setApplications((items) => [{ id: Date.now(), company: company.trim(), role: role.trim(), appliedOn: new Date().toISOString().slice(0, 10), status, resume, nextStep: status === "Saved" ? "Submit application" : "Awaiting response" }, ...items]);
    setCompany(""); setRole(""); setResume("General Resume.pdf"); setStatus("Saved"); setShowForm(false);
  }
  function updateStatus(id: number, nextStatus: JobApplication["status"]) { setApplications((items) => items.map((item) => item.id === id ? { ...item, status: nextStatus, nextStep: nextStatus === "Interview" ? "Interview scheduled" : nextStatus === "Offer" ? "Review offer" : nextStatus === "Saved" ? "Submit application" : "Awaiting response" } : item)); }
  return <div className="space-y-4">
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><ApplicationMetric label="Total applications" value={counts.total} detail="All tracked roles" icon="versions"/><ApplicationMetric label="Active" value={counts.active} detail="Currently in progress" icon="target"/><ApplicationMetric label="Interviews" value={counts.interviews} detail="Preparation needed" icon="calendar"/><ApplicationMetric label="Offers" value={counts.offers} detail="Positive outcomes" icon="check"/></section>
    <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
      <div className="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-base font-bold">Application tracker</h2><p className="mt-0.5 text-[10px] text-slate-500">Keep roles, resumes, and next steps organized.</p></div><button type="button" onClick={() => setShowForm((value) => !value)} className="inline-flex h-9 items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 text-[10px] font-bold text-white"><Icon name="plus"/>{showForm ? "Close form" : "Add application"}</button></div>
      {showForm && <form onSubmit={addApplication} className="grid gap-3 border-b border-slate-100 bg-slate-50/70 p-4 md:grid-cols-2 xl:grid-cols-5"><label><span className="text-[9px] font-bold text-slate-600">Company</span><input required value={company} onChange={(event) => setCompany(event.target.value)} placeholder="Company name" className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs outline-none focus:border-blue-400"/></label><label><span className="text-[9px] font-bold text-slate-600">Role</span><input required value={role} onChange={(event) => setRole(event.target.value)} placeholder="Job title" className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs outline-none focus:border-blue-400"/></label><label><span className="text-[9px] font-bold text-slate-600">Resume used</span><select value={resume} onChange={(event) => setResume(event.target.value)} className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>General Resume.pdf</option><option>Product Designer Resume.pdf</option><option>UX Designer — Fintech.pdf</option></select></label><label><span className="text-[9px] font-bold text-slate-600">Status</span><select value={status} onChange={(event) => setStatus(event.target.value as JobApplication["status"])} className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>Saved</option><option>Applied</option><option>Interview</option><option>Offer</option><option>Rejected</option></select></label><button type="submit" className="mt-auto h-9 rounded-lg bg-slate-950 px-4 text-[10px] font-bold text-white">Save application</button></form>}
      <div className="flex flex-col gap-2 border-b border-slate-100 p-4 sm:flex-row"><div className="relative flex-1"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><Icon name="search"/></span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search company, role, or resume..." className="h-9 w-full rounded-lg bg-slate-50 pl-10 pr-3 text-xs outline-none focus:ring-2 focus:ring-blue-100"/></div><select value={filter} onChange={(event) => setFilter(event.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-[10px] font-bold text-slate-600"><option>All</option><option>Saved</option><option>Applied</option><option>Interview</option><option>Offer</option><option>Rejected</option></select></div>
      <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead><tr className="border-b border-slate-200 bg-slate-50/80 text-[9px] uppercase tracking-[.12em] text-slate-500"><th className="px-5 py-3">Company and role</th><th className="px-5 py-3">Applied on</th><th className="px-5 py-3">Resume used</th><th className="px-5 py-3">Next step</th><th className="px-5 py-3">Status</th><th className="px-5 py-3 text-right">Action</th></tr></thead><tbody className="divide-y divide-slate-100">{filtered.map((item) => <ApplicationRow key={item.id} item={item} onStatusChange={updateStatus} onDelete={(id) => setApplications((items) => items.filter((entry) => entry.id !== id))}/>)}</tbody></table></div>
      {filtered.length === 0 && <div className="px-5 py-14 text-center"><strong className="text-xs">No applications found</strong><p className="mt-1 text-[10px] text-slate-500">Try another filter or add a new opportunity.</p></div>}<div className="border-t border-slate-100 px-5 py-3 text-[9px] text-slate-500">Showing {filtered.length} of {applications.length} applications</div>
    </section>
  </div>;
}
function ApplicationMetric({ label, value, detail, icon }: { label:string; value:number; detail:string; icon:IconName }) { return <article className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-center justify-between"><div><p className="text-[9px] font-bold uppercase tracking-wider text-slate-400">{label}</p><strong className="mt-1 block text-2xl">{value}</strong><span className="text-[9px] text-slate-500">{detail}</span></div><span className="grid size-9 place-items-center rounded-lg bg-blue-50 text-blue-700"><Icon name={icon}/></span></div></article>; }
function ApplicationRow({ item, onStatusChange, onDelete }: { item:JobApplication; onStatusChange:(id:number,status:JobApplication["status"])=>void; onDelete:(id:number)=>void }) { const styles:Record<JobApplication["status"],string>={Saved:"bg-slate-100 text-slate-600",Applied:"bg-blue-50 text-blue-700",Interview:"bg-violet-50 text-violet-700",Offer:"bg-emerald-50 text-emerald-700",Rejected:"bg-red-50 text-red-700"}; const date=new Date(`${item.appliedOn}T00:00:00`).toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"}); return <tr className="hover:bg-slate-50/70"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-blue-50 text-[11px] font-bold text-blue-700">{item.company.charAt(0)}</span><div><strong className="block text-[11px]">{item.company}</strong><span className="text-[9px] text-slate-500">{item.role}</span></div></div></td><td className="px-5 py-3.5 text-[10px] text-slate-500">{date}</td><td className="px-5 py-3.5"><span className="flex items-center gap-2 text-[10px] text-slate-600"><Icon name="document"/>{item.resume}</span></td><td className="px-5 py-3.5 text-[10px] font-medium text-slate-600">{item.nextStep}</td><td className="px-5 py-3.5"><span className={`rounded-full px-2.5 py-1 text-[9px] font-bold ${styles[item.status]}`}>{item.status}</span></td><td className="px-5 py-3.5"><div className="flex justify-end gap-2"><select aria-label={`Update status for ${item.company}`} value={item.status} onChange={(event) => onStatusChange(item.id,event.target.value as JobApplication["status"])} className="h-8 rounded-lg border border-slate-200 bg-white px-2 text-[9px] font-semibold"><option>Saved</option><option>Applied</option><option>Interview</option><option>Offer</option><option>Rejected</option></select><button type="button" onClick={() => { if (window.confirm(`Remove ${item.company} from your applications?`)) onDelete(item.id); }} className="h-8 rounded-lg px-2.5 text-[9px] font-semibold text-red-600 hover:bg-red-50">Remove</button></div></td></tr>; }

function Interview() {
  const interviewTypes = [
    { label: "Behavioral", detail: "Experience and workplace situations", icon: "message" as const },
    { label: "Role-specific", detail: "Questions tailored to your role", icon: "target" as const },
    { label: "Technical", detail: "Skills and problem-solving questions", icon: "spark" as const },
    { label: "HR screening", detail: "Introduction, goals, and culture fit", icon: "user" as const },
  ];
  const [type, setType] = useState("Behavioral");
  const [role, setRole] = useState("Product Designer");
  const [experience, setExperience] = useState("Mid-level (3–5 years)");
  const [started, setStarted] = useState(false);
  const [answer, setAnswer] = useState("");

  if (started) return <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><header className="flex flex-col gap-4 border-b border-slate-100 p-6 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[9px] font-bold uppercase tracking-[0.16em] text-blue-600">Practice session · Question 1 of 8</p><h2 className="mt-1 text-lg font-bold">{type} interview for {role}</h2><p className="mt-1 text-[10px] text-slate-500">{experience}</p></div><button type="button" onClick={()=>{setStarted(false);setAnswer("");}} className="rounded-lg border border-slate-200 px-4 py-2 text-[10px] font-bold text-slate-600 hover:bg-slate-50">End session</button></header><div className="grid min-h-[500px] lg:grid-cols-[1fr_320px]"><div className="p-6 sm:p-8"><div className="flex items-center gap-2 text-[9px] font-bold text-slate-400"><Icon name="clock"/> Take a moment to structure your response</div><h3 className="mt-6 max-w-2xl text-2xl font-bold leading-9">Tell me about a challenging project you worked on and how you handled it.</h3><p className="mt-3 max-w-2xl text-xs leading-5 text-slate-500">Use a specific example. Explain the situation, your responsibility, the action you took, and the result.</p><label className="mt-8 block"><span className="text-[10px] font-bold text-slate-700">Your answer</span><textarea value={answer} onChange={(event)=>setAnswer(event.target.value)} placeholder="Type your answer here, or practice speaking it aloud..." className="mt-2 h-48 w-full resize-none rounded-xl border border-slate-200 p-4 text-xs leading-5 outline-none focus:border-blue-400 focus:ring-4 focus:ring-blue-50"/></label><div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><span className="text-[9px] text-slate-400">{answer.trim().split(/\s+/).filter(Boolean).length} words</span><div className="flex gap-2"><button type="button" className="inline-flex h-10 items-center gap-2 rounded-lg border border-slate-200 px-4 text-[10px] font-bold text-slate-600"><Icon name="mic"/> Practice aloud</button><button type="button" disabled={!answer.trim()} className="h-10 rounded-lg bg-blue-700 px-5 text-[10px] font-bold text-white disabled:cursor-not-allowed disabled:bg-slate-300">Submit answer</button></div></div></div><aside className="border-t border-slate-100 bg-slate-50 p-6 lg:border-l lg:border-t-0"><p className="text-[9px] font-bold uppercase tracking-wider text-slate-400">Answer framework</p>{[["S","Situation","Set the context"],["T","Task","Explain your responsibility"],["A","Action","Describe what you did"],["R","Result","Share the outcome"]].map(([letter,title,detail])=><div key={letter} className="mt-4 flex gap-3"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-blue-100 text-[10px] font-bold text-blue-700">{letter}</span><div><strong className="block text-[10px]">{title}</strong><span className="text-[9px] text-slate-500">{detail}</span></div></div>)}</aside></div></section>;

  return <div className="grid gap-5 xl:grid-cols-[1fr_340px]"><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:p-7"><div><p className="text-[9px] font-bold uppercase tracking-[0.16em] text-blue-600">New practice session</p><h2 className="mt-1 text-xl font-bold">Set up your interview</h2><p className="mt-1 text-[10px] text-slate-500">Choose the interview format and role to receive relevant practice questions.</p></div><fieldset className="mt-7"><legend className="text-[10px] font-bold text-slate-700">Interview type</legend><div className="mt-3 grid gap-3 sm:grid-cols-2">{interviewTypes.map((item)=><button key={item.label} type="button" onClick={()=>setType(item.label)} aria-pressed={type===item.label} className={`flex items-center gap-3 rounded-xl border p-4 text-left transition ${type===item.label?"border-blue-600 bg-blue-50 ring-2 ring-blue-100":"border-slate-200 hover:border-blue-200"}`}><span className={`grid size-9 shrink-0 place-items-center rounded-lg ${type===item.label?"bg-blue-600 text-white":"bg-slate-50 text-slate-500"}`}><Icon name={item.icon}/></span><span><strong className="block text-[11px]">{item.label}</strong><small className="mt-1 block text-[9px] text-slate-500">{item.detail}</small></span></button>)}</div></fieldset><div className="mt-6 grid gap-5 sm:grid-cols-2"><label><span className="text-[10px] font-bold text-slate-700">Target role</span><input value={role} onChange={(event)=>setRole(event.target.value)} placeholder="e.g. Product Designer" className="mt-2 h-11 w-full rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-blue-400 focus:ring-4 focus:ring-blue-50"/></label><label><span className="text-[10px] font-bold text-slate-700">Experience level</span><select value={experience} onChange={(event)=>setExperience(event.target.value)} className="mt-2 h-11 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs outline-none focus:border-blue-400"><option>Entry level (0–2 years)</option><option>Mid-level (3–5 years)</option><option>Senior (6–9 years)</option><option>Lead / Manager (10+ years)</option></select></label></div><div className="mt-7 flex flex-col gap-4 rounded-xl bg-slate-50 p-4 sm:flex-row sm:items-center sm:justify-between"><div><strong className="block text-[11px]">Ready to begin?</strong><p className="mt-1 text-[9px] text-slate-500">8 questions · Approximately 20 minutes · Frontend practice mode</p></div><button type="button" disabled={!role.trim()} onClick={()=>setStarted(true)} className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-blue-700 px-6 text-xs font-bold text-white shadow-md shadow-blue-700/15 hover:bg-blue-800 disabled:bg-slate-300"><Icon name="play"/> Start interview</button></div></section><aside className="space-y-5"><section className="rounded-2xl bg-slate-950 p-6 text-white shadow-sm"><p className="text-[9px] font-bold uppercase tracking-wider text-blue-300">Session preview</p><h2 className="mt-2 text-lg font-bold">{type} interview</h2><div className="mt-5 space-y-4"><PreviewRow label="Target role" value={role||"Not selected"}/><PreviewRow label="Experience" value={experience}/><PreviewRow label="Questions" value="8 questions"/><PreviewRow label="Duration" value="~20 minutes"/></div></section><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><h2 className="text-sm font-bold">Before you start</h2><div className="mt-4 space-y-3"><Tip text="Find a quiet place without distractions."/><Tip text="Keep each answer focused and specific."/><Tip text="Use measurable results when possible."/></div></section></aside></div>;
}
function PreviewRow({label,value}:{label:string;value:string}) { return <div className="flex items-start justify-between gap-4 border-b border-white/10 pb-3 last:border-0 last:pb-0"><span className="text-[9px] text-slate-400">{label}</span><strong className="max-w-44 text-right text-[10px]">{value}</strong></div>; }
function Tip({text}:{text:string}) { return <div className="flex gap-2"><span className="mt-0.5 text-emerald-600"><Icon name="check"/></span><p className="text-[10px] leading-4 text-slate-500">{text}</p></div>; }
function Practice({icon,title,detail}:{icon:IconName;title:string;detail:string}) { return <button className="flex items-center gap-4 rounded-2xl border border-slate-200 bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-blue-200"><span className="grid size-11 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon name={icon}/></span><span className="flex-1"><strong className="block text-xs">{title}</strong><small className="mt-1 block text-[10px] text-slate-400">{detail}</small></span><Icon name="arrow"/></button>; }
function Session({title,date,score}:{title:string;date:string;score:string}) { return <div className="mt-4 flex items-center gap-3 border-t border-slate-100 pt-4"><span className="grid size-8 place-items-center rounded-lg bg-slate-50 text-slate-500"><Icon name="play"/></span><div className="min-w-0 flex-1"><strong className="block truncate text-[10px]">{title}</strong><span className="text-[9px] text-slate-400">{date}</span></div><b className="text-xs text-blue-700">{score}</b></div>; }

function Copilot() { const [messages,setMessages]=useState(["I’m your Career Copilot. What would you like to work on today?"]); const [input,setInput]=useState(""); function send(e:FormEvent){e.preventDefault();if(!input.trim())return;setMessages([...messages,input.trim(),"That’s a great focus. I can help you turn it into a clear, practical next step. Since this is a frontend preview, connect the AI service when you’re ready for live coaching."]);setInput("");} return <div className="grid min-h-[620px] gap-5 xl:grid-cols-[280px_1fr]"><aside className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><button className="flex h-10 w-full items-center justify-center gap-2 rounded-lg bg-blue-700 text-xs font-bold text-white"><Icon name="plus"/> New conversation</button><p className="mb-2 mt-6 text-[9px] font-bold uppercase tracking-wider text-slate-400">Recent</p>{["Plan my next career move","Improve my portfolio story","Prepare for salary negotiation"].map((item,i)=><button key={item} className={`mb-1 flex w-full items-center gap-2 rounded-lg p-3 text-left text-[10px] ${i===0?"bg-blue-50 font-bold text-blue-700":"text-slate-600 hover:bg-slate-50"}`}><Icon name="message"/>{item}</button>)}<div className="mt-6 rounded-xl bg-amber-50 p-4"><Icon name="spark"/><strong className="mt-2 block text-xs">Weekly focus</strong><p className="mt-1 text-[10px] leading-4 text-slate-600">Complete one interview practice session.</p></div></aside><section className="flex min-h-[620px] flex-col rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center gap-3 border-b border-slate-100 p-5"><span className="grid size-10 place-items-center rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 text-white"><Icon name="spark"/></span><div><strong className="block text-sm">Resumind Career Copilot</strong><span className="flex items-center gap-1 text-[9px] text-emerald-600"><i className="size-1.5 rounded-full bg-emerald-500"/> Ready to help</span></div></div><div className="flex-1 space-y-4 overflow-auto p-6">{messages.map((message,i)=><div key={i} className={`flex ${i%3===1?"justify-end":"justify-start"}`}><div className={`max-w-xl rounded-2xl px-4 py-3 text-xs leading-5 ${i%3===1?"rounded-br-sm bg-blue-700 text-white":"rounded-bl-sm bg-slate-100 text-slate-700"}`}>{message}</div></div>)}</div><div className="grid grid-cols-1 gap-2 px-6 pb-3 sm:grid-cols-3">{["Review my career goals","Help tailor my resume","Practice an interview"].map(x=><button key={x} onClick={()=>setInput(x)} className="rounded-lg border border-slate-200 px-3 py-2 text-[9px] font-semibold text-slate-600 hover:border-blue-200">{x}</button>)}</div><form onSubmit={send} className="flex gap-2 border-t border-slate-100 p-4"><input value={input} onChange={e=>setInput(e.target.value)} placeholder="Ask your Career Copilot..." className="h-11 flex-1 rounded-xl bg-slate-50 px-4 text-xs outline-none ring-blue-100 focus:ring-2"/><button aria-label="Send message" className="grid size-11 place-items-center rounded-xl bg-blue-700 text-white"><Icon name="send"/></button></form></section></div>; }

function Settings({profile}:{profile:Profile|null}) { const [saved,setSaved]=useState(false); return <div className="grid gap-5 xl:grid-cols-[220px_1fr]"><aside className="h-fit rounded-2xl border border-slate-200 bg-white p-3 shadow-sm">{[["user","Profile"],["bell","Notifications"],["lock","Privacy & security"],["palette","Appearance"]].map(([icon,label],i)=><button key={label} className={`flex w-full items-center gap-3 rounded-lg p-3 text-left text-xs font-semibold ${i===0?"bg-blue-50 text-blue-700":"text-slate-600 hover:bg-slate-50"}`}><Icon name={icon as IconName}/>{label}</button>)}</aside><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8"><div className="flex items-center gap-4 border-b border-slate-100 pb-6"><Avatar text={profile?.full_name.charAt(0)||"E"} large/><div><h2 className="text-lg font-bold">Personal information</h2><p className="mt-1 text-[10px] text-slate-500">This information appears in your Resumind workspace.</p></div></div><div className="mt-6 grid gap-5 sm:grid-cols-2"><Field label="Full name" value={profile?.full_name||"Employee User"}/><Field label="Work email" value={profile?.email||"employee@company.com"}/><Field label="Job title" value="Product Designer"/><Field label="Location" value="Bengaluru, India"/><label className="sm:col-span-2"><span className="text-[10px] font-bold">Professional bio</span><textarea defaultValue="Product designer focused on thoughtful, user-centered digital experiences." className="mt-2 h-24 w-full resize-none rounded-lg border border-slate-200 p-3 text-xs outline-none focus:border-blue-400"/></label></div><div className="mt-6 flex items-center justify-end gap-3 border-t border-slate-100 pt-6">{saved&&<span className="text-[10px] font-bold text-emerald-600">Changes saved</span>}<button onClick={()=>setSaved(true)} className="h-10 rounded-lg bg-blue-700 px-5 text-xs font-bold text-white">Save changes</button></div></section></div>; }

function Help() { return <><section className="rounded-2xl bg-gradient-to-r from-slate-950 to-blue-950 px-6 py-10 text-center text-white sm:px-12"><span className="mx-auto grid size-11 place-items-center rounded-xl bg-white/10"><Icon name="help"/></span><h2 className="mt-4 text-2xl font-bold">How can we help?</h2><p className="mt-2 text-xs text-slate-300">Search guides, common questions, and product tips.</p><div className="relative mx-auto mt-6 max-w-xl"><span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><Icon name="search"/></span><input placeholder="Search the Help Center..." className="h-12 w-full rounded-xl bg-white pl-11 pr-4 text-xs text-slate-950 outline-none"/></div></section><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><HelpCard icon="document" title="Resume Analyzer" detail="Uploading, scores, and recommendations"/><HelpCard icon="chart" title="Reports & versions" detail="Organize and compare your resumes"/><HelpCard icon="mic" title="Interview practice" detail="Sessions, feedback, and progress"/><HelpCard icon="spark" title="Ask AI" detail="Get help from the AI resume coach"/></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_320px]"><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><h2 className="text-lg font-bold">Frequently asked questions</h2>{["How is my resume score calculated?","What file formats can I upload?","Can I tailor a resume to a specific role?","Is my resume data private?","How do I export or download a report?"].map(q=><button key={q} className="flex w-full items-center justify-between border-b border-slate-100 py-4 text-left text-xs font-semibold last:border-0">{q}<Icon name="plus"/></button>)}</section><aside className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><span className="grid size-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon name="mail"/></span><h2 className="mt-4 text-lg font-bold">Still need help?</h2><p className="mt-2 text-[10px] leading-5 text-slate-500">Our support team is here to help with account and product questions.</p><button className="mt-5 h-10 w-full rounded-lg bg-blue-700 text-xs font-bold text-white">Contact support</button><p className="mt-3 text-center text-[9px] text-slate-400">Typical response within one business day</p></aside></div></>; }

function Brand(){return <div className="flex items-center gap-3 px-2"><span className="grid size-9 place-items-center rounded-xl bg-blue-700 font-bold text-white">R</span><div><strong className="block text-base tracking-tight text-blue-800">RESUMIND</strong><span className="block text-[10px] text-slate-500">AI Resume Intelligence</span></div></div>}
function NavItem({label,icon,href,active,badge}:{label:string;icon:IconName;href:string;active?:boolean;badge?:string}){return <Link href={href} aria-current={active?"page":undefined} className={`flex items-center gap-3 rounded-lg px-3 py-2.5 text-xs font-semibold transition ${active?"bg-blue-50 text-blue-700":"text-slate-600 hover:bg-slate-50 hover:text-slate-950"}`}><Icon name={icon}/><span className="flex-1">{label}</span>{badge&&<span className="rounded bg-amber-50 px-1.5 py-0.5 text-[8px] font-bold text-amber-700">{badge}</span>}</Link>}
function TopBar({initials,section}:{initials:string;section:EmployeeSectionName}){const [title,subtitle]=titles[section];return <header className="border-b border-slate-200 bg-white px-5 py-3 sm:px-6 lg:px-7"><div className="flex items-center justify-between gap-4"><div><h1 className="text-xl font-bold tracking-[-.03em]">{title}</h1><p className="mt-0.5 text-[10px] text-slate-500">{subtitle}</p></div><div className="ml-auto flex items-center gap-2">{section==="reports"&&<Link href="/employee/resume-analyzer/new" className="inline-flex h-9 items-center gap-2 rounded-lg bg-blue-700 px-4 text-[10px] font-bold text-white"><Icon name="plus"/> New analysis</Link>}<NotificationBell/><Avatar text={initials}/></div></div>{section!=="resume-builder"&&<div className="mt-3"><Search placeholder={`Search ${title.toLowerCase()}...`}/></div>}</header>}
function Search({placeholder}:{placeholder:string}){return <div className="relative w-full max-w-xs"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><Icon name="search"/></span><input aria-label={placeholder} placeholder={placeholder} className="h-9 w-full rounded-lg bg-slate-50 pl-10 pr-3 text-xs outline-none focus:ring-2 focus:ring-blue-100"/></div>}
function Avatar({text,large=false}:{text:string;large?:boolean}){return <span className={`grid shrink-0 place-items-center rounded-full bg-blue-50 font-bold text-blue-700 ${large?"size-14 text-lg":"size-8 text-[10px]"}`}>{text}</span>}
function Metric({label,value,detail,icon}:{label:string;value:string;detail:string;icon:IconName}){return <article className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><span className="grid size-9 place-items-center rounded-lg bg-blue-50 text-blue-700"><Icon name={icon}/></span><p className="mt-4 text-[9px] font-bold uppercase tracking-wider text-slate-400">{label}</p><strong className="mt-1 block text-2xl">{value}</strong><span className="mt-2 block text-[10px] font-semibold text-emerald-600">{detail}</span></article>}
function Filter({label,active=false}:{label:string;active?:boolean}){return <button className={`whitespace-nowrap rounded-lg px-4 py-2 text-[10px] font-bold ${active?"bg-slate-950 text-white":"border border-slate-200 bg-white text-slate-600"}`}>{label}</button>}
function SmallStat({value,label}:{value:string;label:string}){return <div className="rounded-xl bg-slate-50 p-3"><strong className="block text-lg">{value}</strong><span className="text-[9px] text-slate-400">{label}</span></div>}
function Field({label,value}:{label:string;value:string}){return <label><span className="text-[10px] font-bold">{label}</span><input defaultValue={value} className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-blue-400"/></label>}
function HelpCard({icon,title,detail}:{icon:IconName;title:string;detail:string}){return <button className="rounded-2xl border border-slate-200 bg-white p-5 text-left shadow-sm hover:border-blue-200"><span className="grid size-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon name={icon}/></span><strong className="mt-4 block text-xs">{title}</strong><span className="mt-1 block text-[10px] leading-4 text-slate-500">{detail}</span><span className="mt-4 flex items-center gap-1 text-[9px] font-bold text-blue-700">Explore articles <Icon name="arrow"/></span></button>}

function Icon({name}:{name:IconName}){const p:Record<IconName,ReactNode>={home:<><path d="m3 11 9-8 9 8"/><path d="M5 10v10h14V10M9 20v-6h6v6"/></>,document:<><path d="M6 2h8l4 4v16H6Z"/><path d="M14 2v5h5M9 12h6M9 16h6"/></>,chart:<><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></>,versions:<><rect x="5" y="4" width="14" height="16" rx="2"/><path d="M8 1h8M9 9h6M9 13h6"/></>,calendar:<><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></>,spark:<><path d="m12 3 1.5 4.5L18 9l-4.5 1.5L12 15l-1.5-4.5L6 9l4.5-1.5Z"/><path d="m19 15 .8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8Z"/></>,settings:<><circle cx="12" cy="12" r="3"/><circle cx="12" cy="12" r="9"/></>,help:<><circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.3 2.3 0 1 1 3 2.2c-.8.3-.8.8-.8 1.8M12 17h.01"/></>,bell:<><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 7h18s-3 0-3-7"/><path d="M10 19h4"/></>,search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,plus:<path d="M12 5v14M5 12h14"/>,arrow:<path d="m9 18 6-6-6-6"/>,download:<><path d="M12 3v12m0 0 4-4m-4 4-4-4"/><path d="M5 20h14"/></>,more:<><circle cx="5" cy="12" r="1" fill="currentColor"/><circle cx="12" cy="12" r="1" fill="currentColor"/><circle cx="19" cy="12" r="1" fill="currentColor"/></>,clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,play:<><circle cx="12" cy="12" r="9"/><path d="m10 8 6 4-6 4Z"/></>,mic:<><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></>,message:<><path d="M4 4h16v13H8l-4 4Z"/><path d="M8 9h8M8 13h5"/></>,target:<><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/></>,bookmark:<path d="M6 3h12v18l-6-4-6 4Z"/>,send:<><path d="m3 3 18 9-18 9 4-9Z"/><path d="M7 12h14"/></>,user:<><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></>,lock:<><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></>,palette:<><circle cx="12" cy="12" r="9"/><circle cx="8" cy="10" r="1"/><circle cx="12" cy="7" r="1"/><circle cx="16" cy="10" r="1"/></>,question:<><circle cx="12" cy="12" r="9"/><path d="M10 9a2 2 0 1 1 2 3v2M12 17h.01"/></>,mail:<><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></>,book:<><path d="M4 3h12a3 3 0 0 1 3 3v15H7a3 3 0 0 1-3-3Z"/><path d="M7 16h12"/></>,check:<path d="m6 12 4 4 8-8"/>};return <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>{p[name]}</svg>}
